<?php
declare(strict_types=1); namespace McpEmail\Tools;
use McpEmail\Intelligence\LinkAnalyzer; use McpEmail\Security\HeaderAnalyzer;
final class GetEmailTool implements ToolInterface {public function name():string{return 'get_email';} public function definition():array{return ['title'=>'E-mail volledig ophalen','description'=>'Haalt precies één e-mail via IMAP UID of intern folder:uid-ID op. Geeft body en veilige HTML terug, maar nooit binaire bijlage-inhoud.','inputSchema'=>['type'=>'object','properties'=>SecurityToolSupport::schema(),'anyOf'=>[['required'=>['uid']],['required'=>['id']]],'additionalProperties'=>false]];} public function call(array $args):array{return SecurityToolSupport::withMessage($args,function(array $m):array{$h=(new HeaderAnalyzer())->analyze($m['headers']);$m['message_id']=$h['message_id'];$m['reply_to']=$h['reply_to'];$m['return_path']=$h['return_path'];$m['cc']=Support::headerAddresses($m['headers'],'Cc');$m['received_date']=Support::headerValue($m['headers'],'Received');$m['links']=(new LinkAnalyzer())->analyze($m['html'],$m['text']);return $m;});}}
